	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Errorf("Get(a) после вытеснения = %q, %v", v, ok)
	}
	if v, ok := c.Get("c"); !ok || v != "3" {
		t.Errorf("Get(c) = %q, %v", v, ok)
	}
}

