func TestConsistentHashEmpty(t *testing.T) {
	r := NewRing(50)
	if got := r.Get("anything"); got != "" {
		t.Errorf("empty ring: Get = %q, want \"\"", got)
	}
}

func TestConsistentHashSingleNode(t *testing.T) {
	r := NewRing(50)
	r.Add("n1")
	for i := 0; i < 100; i++ {
		if got := r.Get("key" + itoa(i)); got != "n1" {
			t.Fatalf("single node: Get(key%d) = %q, want n1", i, got)
		}
	}
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	s := ""
	for i > 0 {
		s = string(rune('0'+i%10)) + s
		i /= 10
	}
	return s
}

func TestConsistentHashMapping(t *testing.T) {
	r := NewRing(100)
	nodes := map[string]bool{"a": true, "b": true, "c": true}
	for n := range nodes {
		r.Add(n)
	}
	seen := map[string]int{}
	for i := 0; i < 1000; i++ {
		g := r.Get("key-" + itoa(i))
		if !nodes[g] {
			t.Fatalf("key %d mapped to unknown node %q", i, g)
		}
		seen[g]++
	}
	for n := range nodes {
		if seen[n] == 0 {
			t.Fatalf("node %q got no keys, distribution: %v", n, seen)
		}
	}
}

func TestConsistentHashStability(t *testing.T) {
	r := NewRing(100)
	for _, n := range []string{"a", "b", "c"} {
		r.Add(n)
	}
	before := make(map[string]string, 1000)
	for i := 0; i < 1000; i++ {
		k := "key-" + itoa(i)
		before[k] = r.Get(k)
	}
	r.Add("d")
	changed := 0
	for k, old := range before {
		if r.Get(k) != old {
			changed++
		}
	}
	// при добавлении 4-го узла «справедливо» меняет владельца ~1/4 ключей; требуем заметно меньше половины
	if changed > 500 {
		t.Errorf("rebalancing moved %d/1000 keys, want <= 500", changed)
	}
	if changed == 0 {
		t.Errorf("no key changed owner after adding node — impl suspicious")
	}
}

func TestConsistentHashOrderIndependent(t *testing.T) {
	r1, r2 := NewRing(64), NewRing(64)
	for _, n := range []string{"x", "y", "z"} {
