func TestSchedulePlan(t *testing.T) {
	jobs := []Job{
		{ID: 1, Priority: 1},
		{ID: 2, Priority: 0, Deps: []int{1}},
		{ID: 3, Priority: 10},
		{ID: 4, Priority: 0, Deps: []int{3}},
	}
