	if got := SchedulePlan(jobs); !reflect.DeepEqual(got, []int{2, 5, 9}) {
		t.Errorf("case2: %v, want [2 5 9]", got)
	}
	// цепочка
	jobs = []Job{{ID: 1}, {ID: 2, Deps: []int{1}}, {ID: 3, Deps: []int{2}}}
	if got := SchedulePlan(jobs); !reflect.DeepEqual(got, []int{1, 2, 3}) {
