        self.assertEqual(Ring(50).get("anything"), "")

    def test_single_node(self):
        r = Ring(50)
        r.add("n1")
        for i in range(100):
            self.assertEqual(r.get("key" + str(i)), "n1")

    def test_mapping(self):
        r = Ring(100)
        for n in ("a", "b", "c"):
            r.add(n)
        seen = {}
        for i in range(1000):
            g = r.get("key-" + str(i))
            self.assertIn(g, {"a", "b", "c"})
            seen[g] = seen.get(g, 0) + 1
        for n in ("a", "b", "c"):
            self.assertGreater(seen.get(n, 0), 0, f"node {n} got no keys: {seen}")

    def test_stability(self):
        r = Ring(100)
        for n in ("a", "b", "c"):
            r.add(n)
        before = {f"key-{i}": r.get(f"key-{i}") for i in range(1000)}
        r.add("d")
        changed = sum(1 for k, old in before.items() if r.get(k) != old)
        self.assertLessEqual(changed, 500, f"moved {changed}/1000 keys")
        self.assertGreater(changed, 0, "no key moved after adding node")

    def test_order_independent(self):
        r1, r2 = Ring(64), Ring(64)
        for n in ("x", "y", "z"):
            r1.add(n)
        for n in ("z", "y", "x"):
